    """Count number of islands in a possibly non‑rectangular grid.
    Cells are connected 4‑directionally. Empty grid returns 0.
    """
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def neighbors(i, j):
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < rows and 0 <= nj < len(grid[ni]):
                yield ni, nj
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            for nx, ny in neighbors(x, y):
