    """Evaluate Reverse Polish Notation expression.
    Supports +, -, *, / where division truncates toward zero.
    Raises ValueError if the expression is malformed.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            if len(stack) < 2:
                raise ValueError('Insufficient operands for operator')
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division
                # Division truncates toward zero
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                res = int(a / b)
            stack.append(res)
        else:
            # assume valid integer token
            stack.append(int(tok))
    if len(stack) != 1:
        # If more than one value remains, the expression is malformed
