def solve(grid):
    """Count the number of islands (connected components of 1s) in a grid.
    The grid may be empty or jagged. Elements are considered land if they
    represent the integer 1 (e.g., 1, True, or the string "1"). All other
    values are treated as water.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def is_land(val):
        try:
            return int(val) == 1
        except Exception:
            return False
    def neighbors(i, j):
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < rows and 0 <= nj < len(grid[ni]):
                yield ni, nj
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            for nx, ny in neighbors(x, y):
                if (nx, ny) not in visited and is_land(grid[nx][ny]):
                    stack.append((nx, ny))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if is_land(val) and (i, j) not in visited:
                count += 1
                dfs(i, j)
    return count

