def solve(s):
    """Validate IPv4 address string."""
    if not isinstance(s, str):
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        # Empty part invalid
        if p == '' or not p.isdigit():
            return False
        # No leading zeros unless the part is exactly '0'
        if len(p) > 1 and p[0] == '0':
            return False
        val = int(p)
        if val < 0 or val > 255:
            return False
    return True

