def solve(n, edges):
    """Return the lexicographically smallest topological ordering of n nodes.
    Nodes are 0..n-1. Edges list contains [a,b] meaning a must come before b.
    If a cycle exists, return [] empty list.
    """
    from heapq import heappush, heappop
    # Build adjacency list and indegree count
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for a, b in edges:
        if 0 <= a < n and 0 <= b < n:
            adj[a].append(b)
            indeg[b] += 1
    # Use a min-heap to always pick the smallest available node
    heap = []
    for i in range(n):
        if indeg[i] == 0:
            heappush(heap, i)
    order = []
    while heap:
        u = heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heappush(heap, v)
    # If not all nodes were processed, a cycle exists
    if len(order) != n:
        return []
    return order

